function exactModelVisualRecommendation(model) {
  const exact = String(model || "").trim().toUpperCase();
  if (!exact) return null;
  const canonical = exact.replace(/[^A-Z0-9]+/g, "");
  return SV_DEVICE_VISUAL_RECOMMENDATIONS.find((item) =>
    String(item.model || "").trim().toUpperCase().replace(/[^A-Z0-9]+/g, "") === canonical
  ) || null;
}

const SV_ASSET_DEFAULT = "__default__";
// Retained only to migrate profiles created by v1.9.35 or older builds that
// could hide the faceplate. It is never offered or preserved as an active state.
const SV_ASSET_NONE = "__none__";

function normaliseFaceplateAsset(value = {}) {
  const faceplate = { fit: "fill", opacity: 1, ...(value && typeof value === "object" ? value : {}) };
  const rawFile = String(faceplate.file || SV_ASSET_DEFAULT).trim();
  const source = String(faceplate.source || "").trim().toLowerCase();
  const hiddenOrLegacyNone = rawFile === SV_ASSET_NONE || source === "none" || faceplate.show === false;

  if (hiddenOrLegacyNone || rawFile === SV_ASSET_DEFAULT || source === "default") {
    // Switch Vision always keeps visible switch artwork. Legacy hidden/none,
    // blank, and invalid states migrate to the model-recommended faceplate.
    faceplate.show = true;
    faceplate.file = SV_ASSET_DEFAULT;
    faceplate.source = "default";
  } else {
    const safe = safeAssetFilename(rawFile);
    if (!safe) {
      faceplate.show = true;
      faceplate.file = SV_ASSET_DEFAULT;
      faceplate.source = "default";
    } else {
      faceplate.show = true;
      faceplate.file = safe;
      faceplate.source = "custom";
    }
  }

  faceplate.fit = ["fill", "contain", "cover"].includes(String(faceplate.fit || "fill").toLowerCase()) ? String(faceplate.fit).toLowerCase() : "fill";
  const opacity = Number(faceplate.opacity);
  faceplate.opacity = Number.isFinite(opacity) ? Math.max(0, Math.min(1, opacity)) : 1;
  return faceplate;
}

function faceplateSelectionValue(value = {}) {
  const faceplate = normaliseFaceplateAsset(value);
  if (faceplate.file === SV_ASSET_DEFAULT) return SV_ASSET_DEFAULT;
  return safeAssetFilename(faceplate.file) || SV_ASSET_DEFAULT;
}

function safeAssetFilename(value) {
  const file = String(value || "").trim();
  if (!file || file.includes("/") || file.includes("\\") || file === "." || file === "..") return "";
  return file;
}

function assetUrl(
  kind,
  file,
  version = SV_VERSION,
  refreshToken = ""
) {
  const safe = safeAssetFilename(file);
  if (!safe) return "";

  const refresh =
    String(refreshToken || "").trim();

  const suffix = refresh
    ? `&r=${encodeURIComponent(refresh)}`
    : "";

  return `/local/switch-vision/${kind}/${encodeURIComponent(safe)}?v=${encodeURIComponent(version)}${suffix}`;
}

